@push('styles')<link rel="stylesheet" href="{{ asset('css/product-editor.css') }}"><style>.product-edit-page{max-width:1180px}.product-section{margin-bottom:16px}.section-title{display:flex;gap:12px;margin-bottom:20px}.section-title>b{width:32px;height:32px;display:grid;place-items:center;border-radius:11px;background:#eef2ff;color:#4f46e5}.section-title h2{margin:0;font-size:16px}.section-title p{margin:5px 0 0;color:#667085;font-size:11px}.form-group label i{color:#f04438;font-style:normal}.form-group small{font-size:9px;color:#98a2b3}.current-files{display:grid;gap:8px;margin-bottom:13px}.current-file{display:flex;gap:10px;align-items:center;border:1px solid #eaecf0;border-radius:12px;padding:10px}.current-file b,.current-file small{display:block}.current-file b{font-size:11px}.current-file small{font-size:9px;color:#98a2b3;margin-top:3px;word-break:break-all}.file-type{width:38px;height:38px;display:grid;place-items:center;border-radius:10px;background:#f2f4f7;font-size:9px;font-weight:900}.file-dropzone{border:2px dashed #cfd5df;border-radius:18px;padding:30px;text-align:center;background:#fafbff;display:flex;flex-direction:column;align-items:center;gap:8px}.uploaded-list{display:grid;gap:8px;margin-top:12px}.uploaded-item{display:grid;grid-template-columns:auto 1fr auto;gap:10px;align-items:center;border:1px solid #eaecf0;border-radius:12px;padding:10px}.uploaded-item strong,.uploaded-item small{display:block}.uploaded-item strong{font-size:11px}.uploaded-item small{font-size:9px;color:#98a2b3}.remove-file{border:0;background:#fff1f3;color:#c01048;border-radius:8px;padding:7px}</style>@endpush
@push('scripts')<script src="{{ asset('js/product-editor.js') }}" defer></script><script>(()=>{const form=document.getElementById('editProductForm'),input=document.getElementById('fileInput'),drop=document.getElementById('dropzone'),list=document.getElementById('uploadedList'),ids=document.getElementById('uploadIds'),format=document.getElementById('fileFormat'),select=document.getElementById('fileFormatSelect'),manual=document.getElementById('fileFormatManual'),page=document.getElementById('pageCount');let uploaded=[];const csrf='{{ csrf_token() }}';const syncFormat=()=>{let v=(manual.value||select.value||'').trim().toLowerCase();if(v&&!v.startsWith('.'))v='.'+v;format.value=v;select.value=Array.from(select.options).some(o=>o.value===v)?v:'';if(select.value)manual.value=v};select.onchange=()=>{manual.value='';format.value=select.value};manual.oninput=syncFormat;function render(){ids.innerHTML=uploaded.map(x=>'<input type="hidden" name="upload_ids[]" value="'+x.id+'">').join('');list.innerHTML=uploaded.map(x=>'<div class="uploaded-item"><div class="file-type">'+x.extension+'</div><div><strong>'+x.name+'</strong><small>'+((x.size/1048576).toFixed(1))+' MB · فایل جدید</small></div><button type="button" class="remove-file" data-id="'+x.id+'">حذف</button></div>').join('')}async function upload(file){const fd=new FormData();fd.append('file',file);const r=await fetch('{{ route('admin.products.uploads.store') }}',{method:'POST',headers:{'X-CSRF-TOKEN':csrf,Accept:'application/json'},body:fd});const d=await r.json();if(!r.ok||!d.ok)throw Error(d.message||'آپلود ناموفق بود');(d.files||[]).forEach(f=>{uploaded.push(f);if(!format.value&&f.format){format.value=f.format;manual.value=f.format;select.value=Array.from(select.options).some(o=>o.value===f.format.toLowerCase())?f.format.toLowerCase():'';if(f.page_count&&!page.value)page.value=f.page_count}});render()}async function handle(files){for(const f of files){try{if(!/\.(pdf|doc|docx|ppt|pptx)$/i.test(f.name)||f.size>209715200)throw Error('فقط PDF، DOC، DOCX، PPT، PPTX و حداکثر ۲۰۰MB مجاز است.');await upload(f)}catch(e){alert(f.name+'\n'+e.message)}}}document.getElementById('chooseFiles').onclick=()=>input.click();input.onchange=()=>handle(input.files);['dragenter','dragover'].forEach(e=>drop.addEventListener(e,x=>{x.preventDefault();drop.classList.add('drag')}));['dragleave','drop'].forEach(e=>drop.addEventListener(e,x=>{x.preventDefault();drop.classList.remove('drag')}));drop.addEventListener('drop',e=>handle(e.dataTransfer.files));list.addEventListener('click',async e=>{const b=e.target.closest('.remove-file');if(!b)return;const id=Number(b.dataset.id);const r=await fetch('{{ url('/admin/products/uploads') }}/'+id,{method:'DELETE',headers:{'X-CSRF-TOKEN':csrf,Accept:'application/json'}});if(r.ok)uploaded=uploaded.filter(x=>x.id!==id);render()});form.onsubmit=()=>{syncFormat();return true}})();</script>@endpush